import limited_client as robot, numpy as np

def rv(q):
 q=np.array(q,dtype=float); return q/np.linalg.norm(q)
def qmul(a,b):
 w,x,y,z=a; W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
def inv(a): return a*np.array([1,-1,-1,-1])
def logq(q):
 q=rv(q)
 if q[0]<0:q=-q
 ang=2*np.arctan2(np.linalg.norm(q[1:]),q[0]); return q[1:]*ang/(np.linalg.norm(q[1:])+1e-12)
x=robot.observe(); qb=np.array(x['robot']['joint_positions']); pb=np.array(x['robot']['tcp_position']); ob=rv(x['robot']['tcp_quaternion_wxyz']); print('base',qb,pb,ob)
for j in range(7):
 x=robot.observe(); q=np.array(x['robot']['joint_positions']); p=np.array(x['robot']['tcp_position']); o=rv(x['robot']['tcp_quaternion_wxyz'])
 a=list(q); a[j]+=.12; a += [.04,.04]; robot.step(a); y=robot.observe(); q1=np.array(y['robot']['joint_positions']); p1=np.array(y['robot']['tcp_position']); o1=rv(y['robot']['tcp_quaternion_wxyz']); dq=q1[j]-q[j]
 print(j,'dq',round(dq,4),'Jp',np.round((p1-p)/dq,3),'Jw',np.round(logq(qmul(o1,inv(o)))/dq,3))
 # return all joints to base and allow settling
 for k in range(3):
  y=robot.observe(); qcur=np.array(y['robot']['joint_positions']); robot.step(list(qb)+[.04,.04])
  y=robot.observe()
 print('err',np.round(np.array(y['robot']['joint_positions'])-qb,3))
